def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Run scheduled jobs sequentially according to their error policies."""
    run_log: list[dict] = []

    for job in jobs:
        name = job["name"]
        error_policy = job["on_error"]["policy"]
        retries = job["on_error"].get("retries", 0)
        attempts = 0
        succeeded = False

        max_attempts = retries + 1 if error_policy == "RETRY" else 1

        while attempts < max_attempts:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if error_policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": name,
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                if error_policy == "RETRY" and attempts < max_attempts:
                    continue

                run_log.append(
                    {
                        "name": name,
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                succeeded = True
                break

        if succeeded:
            run_log.append(
                {
                    "name": name,
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )

    return run_log
